const UXN_VERSION='2026.08.15-notify1';
const uxnSeen=new Map();
function uxnText(el){return (el?.textContent||'').replace(/\s+/g,' ').trim()}
function uxnKind(el){if(el.classList.contains('error'))return'error';if(el.classList.contains('success'))return'success';return'info'}
function uxnTitle(kind){return kind==='error'?'Нужна проверка':kind==='success'?'Готово':'Информация'}
function uxnDecorate(el){if(!(el instanceof HTMLElement)||!el.classList.contains('toast')||el.dataset.uxn===UXN_VERSION)return;const raw=uxnText(el);if(!raw)return;const now=Date.now();const last=uxnSeen.get(raw)||0;if(now-last<1800){el.remove();return}uxnSeen.set(raw,now);for(const [k,t] of uxnSeen){if(now-t>8000)uxnSeen.delete(k)}const kind=uxnKind(el);el.dataset.uxn=UXN_VERSION;el.setAttribute('role',kind==='error'?'alert':'status');el.setAttribute('aria-live',kind==='error'?'assertive':'polite');el.setAttribute('aria-atomic','true');el.classList.add('uxn-toast',`uxn-${kind}`);el.textContent='';const copy=document.createElement('div');copy.className='uxn-copy';const title=document.createElement('strong');title.textContent=uxnTitle(kind);const body=document.createElement('span');body.textContent=raw;copy.append(title,body);const close=document.createElement('button');close.type='button';close.className='uxn-close';close.setAttribute('aria-label','Закрыть уведомление');close.textContent='×';close.addEventListener('click',()=>el.remove());el.append(copy,close);const host=el.parentElement;if(host){const toasts=[...host.querySelectorAll('.toast.uxn-toast')];if(toasts.length>3)toasts.slice(0,toasts.length-3).forEach(x=>x.remove())}}
function uxnScan(){document.querySelectorAll('.toast:not([data-uxn])').forEach(el=>setTimeout(()=>uxnDecorate(el),0))}
let uxnPending=false;function uxnSchedule(){if(uxnPending)return;uxnPending=true;queueMicrotask(()=>{uxnPending=false;uxnScan()})}new MutationObserver(uxnSchedule).observe(document.documentElement,{childList:true,subtree:true});uxnSchedule();